/* Independent image-led tasks for original Netzwerk A1.1 Chapters 2–6 and Plattform reviews.
   All texts, diagrams and interactions are original AmberTheory practice, not publisher exercises. */
(()=>{'use strict';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const data={
2:{title:'Friends, hobbies and work',intro:'Explore hobbies, weekdays and workplaces. Use the visual cards to make a short plan.',cards:[['📸','fotografieren','take photographs'],['🏊','schwimmen','swim'],['📚','lesen','read'],['🎤','singen','sing'],['🍳','kochen','cook'],['🚲','Rad fahren','cycle'],['🩺','die Ärztin','doctor'],['🧑‍🍳','der Koch','cook']],activity:{kind:'schedule',title:'Make a plan using a weekly calendar',choices:['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'],stem:'Hast du am {value} Zeit?',reply:'Ja, am {value} habe ich Zeit.'},check:{q:'Which sentence means “I enjoy reading”?',answers:['Ich lese gern.','Ich bin ein Buch.','Ich komme aus Lesen.'],correct:0,why:'Use the activity verb with gern: Ich lese gern.'}},
3:{title:'Places, transport and directions',intro:'Learn city places, then give directions on an original street grid.',cards:[['🏛️','das Rathaus','town hall'],['🚉','der Bahnhof','railway station'],['🏥','das Krankenhaus','hospital'],['⛪','die Kirche','church'],['🏨','das Hotel','hotel'],['🚇','die U-Bahn','metro'],['🏟️','das Stadion','stadium'],['🌉','der Hafen','harbour']],activity:{kind:'route',title:'Explore an original city route',choices:['Bahnhof','Park','Rathaus','Hotel'],stem:'Entschuldigung, wo ist der {value}?',reply:'Gehen Sie geradeaus. Dann gehen Sie nach rechts.'},check:{q:'What does “Gehen Sie geradeaus” mean?',answers:['Go straight ahead.','Go home.','Turn left.'],correct:0,why:'Geradeaus means straight ahead; the formal imperative uses Sie.'}},
4:{title:'Food, shops and buying things',intro:'Identify food and shopping places, then practise choosing items for a short shopping dialogue.',cards:[['🍞','das Brot','bread'],['🥛','die Milch','milk'],['🧀','der Käse','cheese'],['🍅','die Tomate','tomato'],['🍎','der Apfel','apple'],['🥒','die Gurke','cucumber'],['🥐','die Bäckerei','bakery'],['🛒','der Supermarkt','supermarket']],activity:{kind:'shopping',title:'Build a simple shopping exchange',choices:['das Brot','den Käse','die Milch','die Tomaten'],stem:'Ich kaufe {value}.',reply:'Was brauchen Sie? Ich brauche {value}.'},check:{q:'Choose the correct sentence for buying cheese.',answers:['Ich kaufe der Käse.','Ich kaufe den Käse.','Ich kaufe das Käse.'],correct:1,why:'Der Käse is masculine; in the accusative, der becomes den.'}},
5:{title:'Times, routines and appointments',intro:'Use a clock, a daily routine and a visual schedule to talk about your day.',cards:[['⏰','die Uhrzeit','time'],['🌅','am Morgen','in the morning'],['💻','arbeiten','work'],['🏃','joggen','jog'],['🍽️','frühstücken','have breakfast'],['📅','der Termin','appointment'],['🏠','nach Hause gehen','go home'],['📞','anrufen','call']],activity:{kind:'clock',title:'Explore the clock and tell the time',choices:['08:00','08:15','08:30','08:45'],stem:'Es ist {value} Uhr.',reply:'Wir treffen uns um {value} Uhr.'},check:{q:'Which phrase means half past eight?',answers:['halb neun','halb acht','Viertel vor acht'],correct:0,why:'German halb neun means halfway to nine, or 08:30.'}},
6:{title:'Leisure, invitations and restaurants',intro:'Read leisure activity cards, arrange a date and practise a restaurant invitation.',cards:[['🚴','Fahrrad fahren','cycle'],['🎬','ins Kino gehen','go to the cinema'],['🎂','der Geburtstag','birthday'],['✉️','die Einladung','invitation'],['🍽️','das Restaurant','restaurant'],['📖','lesen','read'],['⚽','Fußball spielen','play football'],['🎫','die Eintrittskarte','ticket']],activity:{kind:'invitation',title:'Create an invitation using a day and activity',choices:['Samstag · ins Kino gehen','Sonntag · Fußball spielen','Freitag · ins Restaurant gehen','Mittwoch · Fahrrad fahren'],stem:'Hast du am {value} Zeit?',reply:'Ja, gern! Danke für die Einladung.'},check:{q:'What is the correct invitation sentence?',answers:['Ich lade dich ein.','Ich einlade dich.','Ich dich lade ein.'],correct:0,why:'In a present-tense statement, the prefix of einladen moves to the end.'}}
};
const speak=t=>{if(!('speechSynthesis' in window))return false;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='de-DE';u.rate=.85;speechSynthesis.speak(u);return true;}catch(_){return false;}};
const state={};
function render(n){const d=data[n];if(!d)return '';
return `<section class="a11-visual-extension" id="chapter-${n}-visual-lab" aria-label="Chapter ${n} visual learning lab">
<div class="a11-ve-heading"><span class="eyebrow">Chapter ${n} · Look, listen, do</span><h5>${E(d.title)}</h5><p>${E(d.intro)}</p></div>
<div class="a11-ve-section"><h6>Discover through visual vocabulary</h6><div class="a11-ve-gallery">${d.cards.map(([icon,de,en])=>`<article class="a11-ve-card"><div class="a11-ve-illustration" aria-hidden="true">${icon}</div><strong lang="de">${E(de)}</strong><span>${E(en)}</span><button type="button" class="view-link" data-ve-speak="${E(de)}">♫ Listen</button></article>`).join('')}</div></div>
<div class="a11-ve-section"><h6>${E(d.activity.title)}</h6>${d.activity.kind==='route'?'<div class="a11-ve-route" role="img" aria-label="Original diagram of a simple city grid with railway station, park, town hall and hotel"><div>🚉<small>Bahnhof</small></div><div class="a11-ve-road">→</div><div>🌳<small>Park</small></div><div class="a11-ve-road">↓</div><div>🏛️<small>Rathaus</small></div><div class="a11-ve-road">→</div><div>🏨<small>Hotel</small></div></div>':''}
${d.activity.kind==='clock'?'<div class="a11-ve-clock" aria-label="Clock visual"><span class="a11-ve-clock-face"><i></i><b></b></span><span>Move through the time choices below to read different appointments.</span></div>':''}
${d.activity.kind==='schedule'?'<div class="a11-ve-week"><span>Mo</span><span>Di</span><span>Mi</span><span>Do</span><span>Fr</span><span>Sa</span><span>So</span></div>':''}
${d.activity.kind==='shopping'?'<div class="a11-ve-basket" aria-hidden="true">🛒 <span>🍞</span> <span>🧀</span> <span>🥛</span> <span>🍅</span></div>':''}
${d.activity.kind==='invitation'?'<div class="a11-ve-envelope" aria-hidden="true">✉️ <span>Einladung · Einladungskarte</span></div>':''}
<div class="a11-ve-choices" role="group" aria-label="Choose a practice option">${d.activity.choices.map((o,i)=>`<button type="button" data-ve-choice="${n}:${i}" aria-pressed="${i===0}" class="${i===0?'selected':''}">${E(o)}</button>`).join('')}</div><div class="a11-ve-live" aria-live="polite"><strong lang="de" data-ve-sentence="${n}">${E(d.activity.stem.replace('{value}',d.activity.choices[0]))}</strong><p lang="de" data-ve-response="${n}">${E(d.activity.reply.replace('{value}',d.activity.choices[0]))}</p><button class="view-link" type="button" data-ve-play="${n}">♫ Hear the conversation</button></div></div>
<div class="a11-ve-section"><h6>Check your understanding</h6><p>${E(d.check.q)}</p><div class="a11-ve-answers" role="group" aria-label="Knowledge check">${d.check.answers.map((a,i)=>`<button type="button" data-ve-answer="${n}:${i}">${E(a)}</button>`).join('')}</div><p class="a11-ve-feedback" aria-live="polite" data-ve-feedback="${n}">Choose an answer to see feedback.</p></div></section>`;}
function init(root=document){root.querySelectorAll('.a11-visual-extension').forEach(section=>{const n=Number(section.id.match(/chapter-(\d+)-/)?.[1]);const d=data[n];if(!d)return;
section.querySelectorAll('[data-ve-speak]').forEach(b=>b.addEventListener('click',()=>speak(b.dataset.veSpeak)));
section.querySelectorAll('[data-ve-choice]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.veChoice.split(':')[1]),v=d.activity.choices[i];section.querySelectorAll('[data-ve-choice]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});section.querySelector('[data-ve-sentence]').textContent=d.activity.stem.replace('{value}',v);section.querySelector('[data-ve-response]').textContent=d.activity.reply.replace('{value}',v);if(n===5){const clock=section.querySelector('.a11-ve-clock-face');if(clock)clock.style.setProperty('--minutes',String(i*90)+'deg');}}));
section.querySelector('[data-ve-play]')?.addEventListener('click',()=>speak(section.querySelector('[data-ve-sentence]').textContent+' '+section.querySelector('[data-ve-response]').textContent));
section.querySelectorAll('[data-ve-answer]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.veAnswer.split(':')[1]);section.querySelector('[data-ve-feedback]').textContent=(i===d.check.correct?'Correct. ':'Try again. ')+d.check.why;}));});}
const reviews={3:{title:'Plattform 1 · Visual revision',prompt:'Review greetings, hobbies and places using these original image cues.',items:[['👋','Hallo! Wie heißt du?'],['🎤','Ich singe gern.'],['🚉','Wo ist der Bahnhof?']]},6:{title:'Plattform 2 · Visual revision',prompt:'Review food, time, invitations and everyday conversation.',items:[['🍞','Ich kaufe Brot.'],['🕗','Es ist acht Uhr.'],['✉️','Ich lade dich ein.']]}};
function renderReview(n){const d=reviews[n];return d?`<section class="a11-ve-review" aria-label="${E(d.title)}"><h6>${E(d.title)}</h6><p>${E(d.prompt)}</p><div class="a11-ve-gallery">${d.items.map(([ic,de])=>`<div class="a11-ve-card"><span class="a11-ve-illustration" aria-hidden="true">${ic}</span><strong lang="de">${E(de)}</strong><button type="button" class="view-link" data-ve-review-speak="${E(de)}">♫ Listen</button></div>`).join('')}</div></section>`:'';}
function initReview(root=document){root.querySelectorAll('[data-ve-review-speak]').forEach(b=>b.addEventListener('click',()=>speak(b.dataset.veReviewSpeak)));}
window.GERMAN_A11_VISUAL_EXTENSIONS={render,init,renderReview,initReview};
})();